mapper.select:
select count(1)
  from t_invoice i
 where i.del_flag = '0' and i.invoice_kind = #{kind}

select 
  from t_invoice i
  left join t_invoice_apply a on a.apply_id = i.apply_id
 where i.del_flag = '0'
and i.enterprise_id = #{q.enterpriseId}
and i.invoice_kind = #{q.invoiceKind}
and i.file_status = #{q.fileStatus}
and i.apply_id = #{q.applyId}

    and (i.invoice_no like concat('%', #{q.keyword}, '%')
         or a.apply_no like concat('%', #{q.keyword}, '%')
         or i.seller_name like concat('%', #{q.keyword}, '%')
         or i.buyer_name like concat('%', #{q.keyword}, '%'))

and i.invoice_date >= #{q.startDate}
and i.invoice_date <= #{q.endDate}
 order by i.invoice_date desc, i.invoice_id desc
